// Synthetic public v80 transaction encoded by the pinned Sentry SDK's
// buildSentryRegistration. This is a codec fixture, never a broadcast.
export const SENTRY_TXID = '70bddf11d1d68c18b8447e4abd27266077035e1a945342258e91f0b1d6923dec';
export const SENTRY_TX_HEX = '';
export const SENTRY_COLLATERAL_TXID = '22'.repeat(32);
export function sentryNodeResponse(genesisHash: string) {
  return {
    chain: { genesisHash },
    node: {
      proTxHash: SENTRY_TXID,
      service: '192.0.2.10:8369',
      nevmAddress: '0x' + '12'.repeat(20),
      collateralOutpoint: { txid: SENTRY_COLLATERAL_TXID, vout: 1 },
    },
  };
}
